import{_ as e}from"./chunks/rover_manual_controls.DWf4LXLd.js";import{_ as a,c as r,o,al as i}from"./chunks/framework.D8UyiDWg.js";const u=JSON.parse('{"title":"Manual Modes","description":"","frontmatter":{},"headers":[],"relativePath":"uk/flight_modes_rover/manual.md","filePath":"uk/flight_modes_rover/manual.md"}'),d={name:"uk/flight_modes_rover/manual.md"};function s(n,t,h,l,c,m){return o(),r("div",null,t[0]||(t[0]=[i('<h1 id="manual-modes" tabindex="-1">Manual Modes <a class="header-anchor" href="#manual-modes" aria-label="Permalink to &quot;Manual Modes&quot;">​</a></h1><p>Manual modes require stick inputs from the user to drive the vehicle.</p><p><img src="'+e+'" alt="Manual Controls"></p><p>The sticks provide the same &quot;high level&quot; control effects over direction and rate of movement in all manual modes:</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Left stick up/down</th><th>Left stick left/right</th><th>Right stick left/right</th></tr></thead><tbody><tr><td>Ackermann</td><td>Drive the rover forwards/backwards (controlling speed)</td><td>-</td><td>Make a left/right turn (controlling steering angle in <a href="#manual-mode">Manual mode</a>, and yaw rate in <a href="#acro-mode">Acro</a>, <a href="#stabilized-mode">Stabilized</a> and <a href="#position-mode">Position</a> modes).</td></tr><tr><td>Differential</td><td>Drive the rover forwards/backwards (controlling speed).</td><td>-</td><td>Make a left/right turn (controlling speed difference in <a href="#manual-mode">Manual mode</a>, and yaw rate in <a href="#acro-mode">Acro</a>, <a href="#stabilized-mode">Stabilized</a> and <a href="#position-mode">Position</a> modes).</td></tr><tr><td>Mecanum</td><td>Drive the rover forwards/backwards (controlling speed)</td><td>Make a left/right turn (controlling speed difference in <a href="#manual-mode">Manual mode</a>, and yaw rate in <a href="#acro-mode">Acro</a>, <a href="#stabilized-mode">Stabilized</a> and <a href="#position-mode">Position</a> modes).</td><td>Drive the rover left/right (controlling speed).</td></tr></tbody></table><p>The manual modes provide progressively increasing levels of autopilot support for maintaining a course, speed, and rate of turn, compensating for external factors such as slopes or uneven terrain.</p><table tabindex="0"><thead><tr><th>Режим</th><th>Опис</th></tr></thead><tbody><tr><td><a href="./manual.html#manual-mode">Manual</a></td><td>No autopilot support. User is responsible for keeping the rover on the desired course and maintaining speed and rate of turn.</td></tr><tr><td><a href="./manual.html#acro-mode">Acro</a></td><td>+ Maintains the yaw rate (feels more like driving a car than manual mode). <br>+ Allows maximum yaw rate to be limited (protects against roll over).</td></tr><tr><td><a href="./manual.html#stabilized-mode">Stabilized</a></td><td>+ Maintains the yaw (significantly better at holding a straight line).</td></tr><tr><td><a href="./manual.html#position-mode">Position</a></td><td>+ Maintains the course (best mode for driving a straight line).<br>+ Maintains speed against disturbances, e.g. when driving up a hill.<br>+ Allows maximum speed to be limited.</td></tr></tbody></table><details class="details custom-block"><summary>Details</summary><p>Overview mode mapping to control effect</p><table tabindex="0"><thead><tr><th>Режим</th><th>Speed</th><th>Turning</th><th>Required measurements</th></tr></thead><tbody><tr><td><a href="#manual-mode">Manual</a></td><td>Directly map stick input to motor command.</td><td>Directly map stick input to steering angle/speed difference.</td><td>None.</td></tr><tr><td><a href="#acro-mode">Acro</a></td><td>Directly map stick input to motor command.</td><td>Stick input creates a yaw rate setpoint for the control system to regulate.</td><td>yaw rate.</td></tr><tr><td><a href="#stabilized-mode">Stabilized</a></td><td>Directly map stick input to motor commands.</td><td>Stick input creates a yaw rate setpoint for the control system to regulate. If this setpoint is zero (stick is centered) the control system will maintain the current yaw (heading) of the rover.</td><td>Yaw rate and yaw.</td></tr><tr><td><a href="#position-mode">Position</a></td><td>Stick input creates a speed setpoint for the control system to regulate.</td><td>Stick input creates a yaw rate setpoint for the control system to regulate. If this setpoint is zero (stick is centered) the control system will keep the rover driving in a straight line.</td><td>yaw rate, yaw, speed and global position (GPS).</td></tr></tbody></table></details><h2 id="ручнии-режим" tabindex="-1">Ручний режим <a class="header-anchor" href="#ручнии-режим" aria-label="Permalink to &quot;Ручний режим&quot;">​</a></h2><p>In this mode the stick inputs are directly mapped to motor commands. The rover does not attempt to maintain a specific orientation or compensate for external factors like slopes or uneven terrain! The user is responsible for making the necessary adjustments to the stick inputs to keep the rover on the desired course.</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Left stick up/down</th><th>Left stick left/right</th><th>Right stick left/right</th></tr></thead><tbody><tr><td>Ackermann</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Move the steering angle to the left/right.</td></tr><tr><td>Differential</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Yaw the rover to the left/right.</td></tr><tr><td>Mecanum</td><td>Drive the rover forwards/backwards.</td><td>Yaw the rover to the left/right.</td><td>Drive the rover left/right</td></tr></tbody></table><p>For the configuration/tuning of this mode see <a href="./../config_rover/basic_setup.html">Basic Setup</a>.</p><h2 id="acro-mode" tabindex="-1">Acro Mode <a class="header-anchor" href="#acro-mode" aria-label="Permalink to &quot;Acro Mode&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This mode requires a yaw rate measurement.</p></div><p>In this mode the vehicle regulates its yaw rate to a setpoint (but does not stabilize heading or regulate speed).</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Left stick up/down</th><th>Left stick left/right</th><th>Right stick left/right</th></tr></thead><tbody><tr><td>Ackermann</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will attempt to maintain a zero yaw rate (minimal disturbance rejection).</td></tr><tr><td>Differential</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will attempt to maintain a zero yaw rate (minimal disturbance rejection)</td></tr><tr><td>Mecanum</td><td>Drive the rover forwards/backwards.</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will attempt to maintain a zero yaw rate (minimal disturbance rejection)</td><td>Drive the rover left/right</td></tr></tbody></table><p>For the configuration/tuning of this mode see <a href="./../config_rover/rate_tuning.html">Rate tuning</a>.</p><h2 id="stabilized-mode" tabindex="-1">Stabilized Mode <a class="header-anchor" href="#stabilized-mode" aria-label="Permalink to &quot;Stabilized Mode&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This mode requires a yaw rate and yaw estimate.</p></div><p>In this mode the vehicle regulates its yaw rate to a setpoint and will maintain its heading if this setpoint is zero (but does not regulate speed). Compared to <a href="#acro-mode">Acro mode</a>, this mode is much better at driving in a straight line as it can more effectively reject disturbances.</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Left stick up/down</th><th>Left stick left/right</th><th>Right stick left/right</th></tr></thead><tbody><tr><td>Ackermann</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the current yaw.</td></tr><tr><td>Differential</td><td>Drive the rover forwards/backwards.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the current yaw.</td></tr><tr><td>Mecanum</td><td>Drive the rover forwards/backwards.</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the current yaw.</td><td>Drive the rover left/right</td></tr></tbody></table><p>For the configuration/tuning of this mode see <a href="./../config_rover/attitude_tuning.html">Attitude tuning</a>.</p><h2 id="position-mode" tabindex="-1">Position Mode <a class="header-anchor" href="#position-mode" aria-label="Permalink to &quot;Position Mode&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This mode requires a yaw rate, yaw, speed and global position estimate.</p></div><p>This is the manual mode with the most autopilot support. The vehicle regulates its yaw rate and speed to a setpoint. If the yaw rate setpoint is zero, the controller will remember the GPS coordinates and yaw (heading) of the vehicle and use those to construct a line that the rover will then follow (course control). This offers the highest amount of disturbance rejection, which leads to the best straight line driving behavior.</p><table tabindex="0"><thead><tr><th>Rover Type</th><th>Left stick up/down</th><th>Left stick left/right</th><th>Right stick left/right</th></tr></thead><tbody><tr><td>Ackermann</td><td>Stick position sets a forward/back speed setpoint. The vehicle attempts to maintain this speed on slopes etc.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the course of the rover.</td></tr><tr><td>Differential</td><td>Stick position sets a forward/back speed setpoint. The vehicle attempts to maintain this speed on slopes etc.</td><td>-</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the course of the rover.</td></tr><tr><td>Mecanum</td><td>Stick position sets a forward/back speed setpoint. The vehicle attempts to maintain this speed on slopes etc.</td><td>Create a yaw rate setpoint for the control system to regulate. If this input is zero the control system will maintain the course of the rover.</td><td>Stick position sets a left/right speed setpoint. The vehicle attempts to maintain this speed on slopes etc.</td></tr></tbody></table><p>For the configuration/tuning of this mode see <a href="./../config_rover/velocity_tuning.html">Velocity tuning</a>.</p>',27)]))}const g=a(d,[["render",s]]);export{u as __pageData,g as default};
